CREATE TABLE IF NOT EXISTS rooms(room_id INTEGER PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS items(item_id BIGSERIAL PRIMARY KEY,prototype_key VARCHAR(64) UNIQUE NOT NULL,name VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS character_stats(character_id BIGINT PRIMARY KEY REFERENCES characters(character_id),hp INTEGER NOT NULL DEFAULT 100,max_hp INTEGER NOT NULL DEFAULT 100,mana INTEGER NOT NULL DEFAULT 100,max_mana INTEGER NOT NULL DEFAULT 100);
CREATE TABLE IF NOT EXISTS character_items(character_id BIGINT NOT NULL REFERENCES characters(character_id),item_id BIGINT NOT NULL REFERENCES items(item_id),quantity INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(character_id,item_id));
